function hasValidPath(grid) {
  // Draw every piece as a 3x3 block of pixels and flood-fill the open pixels.
  const m = grid.length, n = grid[0].length;
  const H = 3 * m, W = 3 * n;
  const open = Array.from({ length: H }, () => new Array(W).fill(false));
  const sides = { 1: 'LR', 2: 'UD', 3: 'LD', 4: 'RD', 5: 'LU', 6: 'RU' };
  for (let r = 0; r < m; r++) {
    for (let c = 0; c < n; c++) {
      const cr = 3 * r + 1, cc = 3 * c + 1;
      open[cr][cc] = true;
      for (const s of sides[grid[r][c]]) {
        if (s === 'U') open[cr - 1][cc] = true;
        if (s === 'D') open[cr + 1][cc] = true;
        if (s === 'L') open[cr][cc - 1] = true;
        if (s === 'R') open[cr][cc + 1] = true;
      }
    }
  }
  const seen = Array.from({ length: H }, () => new Array(W).fill(false));
  const queue = [[1, 1]];
  seen[1][1] = true;
  for (let q = 0; q < queue.length; q++) {
    const [r, c] = queue[q];
    for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const nr = r + dr, nc = c + dc;
      if (nr >= 0 && nr < H && nc >= 0 && nc < W && open[nr][nc] && !seen[nr][nc]) {
        seen[nr][nc] = true;
        queue.push([nr, nc]);
      }
    }
  }
  return seen[3 * m - 2][3 * n - 2];
}

