function generate(rand, size) {
  const large = size === 'large';
  const m = large ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 4);
  const n = large ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 4);
  const grid = Array.from({ length: m }, () => Array.from({ length: n }, () => 1 + Math.floor(rand() * 6)));
  const mode = rand();
  if (mode < 0.25) return [grid];
  // Carve a winding simple path from (0, 0) to (m - 1, n - 1) with a randomised DFS.
  const moves = [[-1, 0], [0, 1], [1, 0], [0, -1]];
  const tileOf = { '1,3': 1, '0,2': 2, '2,3': 3, '1,2': 4, '0,3': 5, '0,1': 6 };
  const tile = (a, b) => tileOf[[a, b].sort((x, y) => x - y).join(',')];
  const used = Array.from({ length: m }, () => new Array(n).fill(false));
  const path = [[0, 0]];
  used[0][0] = true;
  while (true) {
    const [r, c] = path[path.length - 1];
    if (r === m - 1 && c === n - 1) break;
    const options = [];
    for (let d = 0; d < 4; d++) {
      const nr = r + moves[d][0], nc = c + moves[d][1];
      if (nr >= 0 && nr < m && nc >= 0 && nc < n && !used[nr][nc]) options.push([nr, nc]);
    }
    if (options.length === 0) { path.pop(); continue; }
    const next = options[Math.floor(rand() * options.length)];
    used[next[0]][next[1]] = true;
    path.push(next);
  }
  const dirTo = ([r, c], [nr, nc]) => moves.findIndex(([dr, dc]) => r + dr === nr && c + dc === nc);
  for (let i = 0; i < path.length; i++) {
    const [r, c] = path[i];
    let entry = i > 0 ? dirTo(path[i], path[i - 1]) : -1;
    let exit = i + 1 < path.length ? dirTo(path[i], path[i + 1]) : -1;
    if (entry === -1 && exit === -1) continue;
    if (entry === -1) do { entry = Math.floor(rand() * 4); } while (entry === exit);
    if (exit === -1) do { exit = Math.floor(rand() * 4); } while (exit === entry);
    grid[r][c] = tile(entry, exit);
  }
  if (mode < 0.5 && path.length > 1) {
    // Break the path at one random cell; the answer may become false.
    const [r, c] = path[Math.floor(rand() * path.length)];
    grid[r][c] = 1 + Math.floor(rand() * 6);
  }
  return [grid];
}
